import { readFileSync, realpathSync } from "node:fs";
import { fileURLToPath } from "node:url";

// Commit convention (ADR 0020, PLRNUI-447): add|fix|chore(PLRNUI-<n>): <message>
const CONVENTION = /^(add|fix|chore)\(PLRNUI-[0-9]+\): \S.*/;
// Messages generated by git itself when merging a branch (e.g. bringing texo/v1 into a ticket branch).
const GIT_MERGE = /^Merge (pull request|branch|remote-tracking branch) /;

export function validateCommitMessage(message) {
  const subject = String(message ?? "").split(/\r?\n/)[0];
  if (CONVENTION.test(subject)) return { ok: true };
  if (GIT_MERGE.test(subject)) return { ok: true };
  return { ok: false, reason: `commit subject must match ${CONVENTION}: got "${subject}"` };
}

// realpath on both sides: a symlinked invocation path must not turn the check into a silent no-op.
const isCli = process.argv[1] && realpathSync(process.argv[1]) === realpathSync(fileURLToPath(import.meta.url));
if (isCli) {
  const file = process.argv[2];
  if (!file) {
    console.error("usage: check-commit-msg.mjs <commit-message-file>");
    process.exit(2);
  }
  const result = validateCommitMessage(readFileSync(file, "utf8"));
  if (!result.ok) {
    console.error(result.reason);
    process.exit(1);
  }
}
